style.css:
/* Nhắm mục tiêu tất cả các thẻ button và input dạng nút */
button,
input[type="button"],
input[type="submit"],
input[type="reset"] {
  background-color: #007bff; /* Màu nền ban đầu */
  color: #ffffff;
  border: none;
  padding: 10px 20px;
  cursor: pointer;
  /* Hiệu ứng đổi màu trong 0.1 giây */
  transition: background-color 0.1s ease, color 0.1s ease;
}

/* Trạng thái khi rê chuột vào (Hover) */
button:hover,
input[type="button"]:hover,
input[type="submit"]:hover,
input[type="reset"]:hover {
  background-color: #0056b3; /* Màu nền mới khi rê chuột */
  /* Kích hoạt animation lên xuống liên tục */
  animation: bounceUpDown 0.6s infinite alternate ease-in-out;
}

/* Định nghĩa chuyển động lên xuống */
@keyframes bounceUpDown {
  0% {
    transform: translateY(0);
  }
  100% {
    transform: translateY(-6px); /* Độ cao nút nảy lên, có thể chỉnh lại */
  }
}
